import os
import joblib
import mlflow
import pandas as pd
import xgboost as xgb

from sklearn.compose import make_column_transformer
from sklearn.preprocessing import StandardScaler, OneHotEncoder
from sklearn.pipeline import make_pipeline
from sklearn.model_selection import GridSearchCV
from sklearn.metrics import accuracy_score, f1_score, roc_auc_score


# Load train/test data generated by the data-prep stage

X_train = pd.read_csv("Xtrain.csv")
X_test = pd.read_csv("Xtest.csv")
y_train = pd.read_csv("ytrain.csv").squeeze()
y_test = pd.read_csv("ytest.csv").squeeze()

print("Train/test datasets loaded successfully.")
print(f"Training records: {len(X_train)}")
print(f"Testing records: {len(X_test)}")


# Identify numerical and categorical columns


categorical_features = X_train.select_dtypes(
    include=["object"]
).columns.tolist()

numerical_features = X_train.select_dtypes(
    exclude=["object"]
).columns.tolist()

print(f"Categorical features: {categorical_features}")
print(f"Numerical features: {numerical_features}")


# Create preprocessing pipeline


preprocessor = make_column_transformer(
    (
        StandardScaler(),
        numerical_features
    ),
    (
        OneHotEncoder(handle_unknown="ignore"),
        categorical_features
    )
)


# Define XGBoost model


xgb_model = xgb.XGBClassifier(
    objective="binary:logistic",
    eval_metric="logloss",
    random_state=42
)


model_pipeline = make_pipeline(
    preprocessor,
    xgb_model
)



# Hyperparameter tuning


param_grid = {
    "xgbclassifier__n_estimators": [100, 200],
    "xgbclassifier__max_depth": [3, 5],
    "xgbclassifier__learning_rate": [0.05, 0.1],
    "xgbclassifier__subsample": [0.8, 1.0]
}

grid_search = GridSearchCV(
    estimator=model_pipeline,
    param_grid=param_grid,
    cv=3,
    scoring="f1",
    n_jobs=-1,
    verbose=1
)

print("Starting hyperparameter tuning...")

grid_search.fit(X_train, y_train)

best_model = grid_search.best_estimator_
best_params = grid_search.best_params_

print("Hyperparameter tuning completed.")
print(f"Best CV F1-score: {grid_search.best_score_:.4f}")
print(f"Best parameters: {best_params}")



# Model evaluation


y_pred = best_model.predict(X_test)
y_pred_proba = best_model.predict_proba(X_test)[:, 1]

test_accuracy = accuracy_score(y_test, y_pred)
test_f1_macro = f1_score(y_test, y_pred, average="macro")
test_roc_auc = roc_auc_score(y_test, y_pred_proba)

print(f"Test Accuracy: {test_accuracy:.4f}")
print(f"Test Macro-F1: {test_f1_macro:.4f}")
print(f"Test ROC-AUC: {test_roc_auc:.4f}")


# MLflow experiment tracking

MLFLOW_DIR = os.path.join(
    "model_building",
    "mlruns"
)

os.makedirs(MLFLOW_DIR, exist_ok=True)

mlflow.set_tracking_uri(
    "file://" + os.path.abspath(MLFLOW_DIR)
)

mlflow.set_experiment("Tourism_Package_Prediction")

with mlflow.start_run(run_name="XGBoost_Tuned_Model"):

    mlflow.log_params({
        "n_estimators": best_params["xgbclassifier__n_estimators"],
        "max_depth": best_params["xgbclassifier__max_depth"],
        "learning_rate": best_params["xgbclassifier__learning_rate"],
        "subsample": best_params["xgbclassifier__subsample"]
    })

    mlflow.log_metrics({
        "cv_f1_score": grid_search.best_score_,
        "test_accuracy": test_accuracy,
        "test_f1_macro": test_f1_macro,
        "test_roc_auc": test_roc_auc
    })

print("MLflow experiment tracking completed successfully.")


# Save best model

MODEL_PATH = os.path.join(
    "model_building",
    "best_tourism_package_model.pkl"
)

joblib.dump(best_model, MODEL_PATH)

print("Best model saved successfully.")
print(f"Model path: {MODEL_PATH}")
print(f"Model file exists: {os.path.exists(MODEL_PATH)}")
